frame.store("_a_bad_stretch_above", { let __default_7372 = Value::Int("3".parse().expect("integer literal")); let __signature_7370 = Signature { name: "_a_bad_stretch_above".into(), positional: vec!["memory".into(),"look_back".into()], positional_only: 0, defaults: vec![__default_7372], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_7373 = Value::dict(); __attrs_7373.dict_set(Value::from("__doc__"), Value::from("True when the last few things the person said were about a bad stretch of their own.\n\n    \"who can i talk to\" is the same line in a painting thread and in a lonely one, and the reply\n    that fits the second (\"the GP is not only for a body\") is a cold, wrong answer to the first -\n    it tells somebody looking for a class that the bot thinks they are ill. So the GP line is only\n    offered when a turn or two before this one was about a mood, a funeral or a diagnosis.\n    "))?; __attrs_7373.dict_set(Value::from("__defaults__"), Value::tuple(__signature_7370.defaults.clone()))?; let __kwdefaults_7374 = Value::dict(); __attrs_7373.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_7369 = Frame::module(frame.globals.clone()); let mut __function_7371 = NativeFunction::qualified_with_origin("_a_bad_stretch_above".into(), "_a_bad_stretch_above".into(), "bot.compose.fallback".into(), __attrs_7373, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/compose/fallback.py", first: 12859, last: 12874, qualname: "_a_bad_stretch_above" }, closure: __closure_7369.clone(), freevars: vec![] }, move |rt, args| __py_316::_a_bad_stretch_above(rt, __closure_7369.clone(), &__signature_7370, args)); __function_7371 })?;
