frame.store("_who_for_the_thread", { let __default_7389 = Value::None; let __signature_7387 = Signature { name: "_who_for_the_thread".into(), positional: vec!["memory".into(),"clean".into(),"understood".into()], positional_only: 0, defaults: vec![__default_7389], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_7390 = Value::dict(); __attrs_7390.dict_set(Value::from("__doc__"), Value::from("The person to take a bare \"who do i call about it\" to, or a reply asking what it is.\n\n    Read only in `_unknown`, so a line with a subject of its own never gets here and the looser\n    reading costs nothing: what it replaces is the shrug. Three rungs, in the order of how much\n    they know about this person: the trouble they named a turn ago (the same reading that names a\n    person for a line that says it outright), then the actor the bot's own answer named a moment\n    ago (\"report it to the council\"). With neither, the honest reply is the route list for a call\n    and the talk-to lines for a person to talk to, plus the one question that would settle it.\n    "))?; __attrs_7390.dict_set(Value::from("__defaults__"), Value::tuple(__signature_7387.defaults.clone()))?; let __kwdefaults_7391 = Value::dict(); __attrs_7390.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_7386 = Frame::module(frame.globals.clone()); let mut __function_7388 = NativeFunction::qualified_with_origin("_who_for_the_thread".into(), "_who_for_the_thread".into(), "bot.compose.fallback".into(), __attrs_7390, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/compose/fallback.py", first: 12900, last: 12958, qualname: "_who_for_the_thread" }, closure: __closure_7386.clone(), freevars: vec![] }, move |rt, args| __py_319::_who_for_the_thread(rt, __closure_7386.clone(), &__signature_7387, args)); __function_7388 })?;
frame.store("_trouble", { let __signature_7393 = Signature { name: "_trouble".into(), positional: vec!["memory".into(),"clean".into(),"words".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_7395 = Value::dict(); __attrs_7395.dict_set(Value::from("__doc__"), Value::from("A statement of trouble (\"my landlord wont fix the damp\") still deserves the person who\n    can settle it. Only with a trouble cue in the line: \"i paid off my mortgage\" is not a\n    money problem, so the plain nod stays.\n\n    A grown-up's plain symptom is not one of those: \"ive got a sore throat\" wants the care line\n    the composer already has (rest, warm drinks), not a queue for the GP, so that row is only\n    named when the line asks something (\"should i worry\", \"how long does it last\"). A baby's\n    symptom is different: \"my baby has a cough\" is the health visitor's, question or not.\n    "))?; __attrs_7395.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_7396 = Value::dict(); __attrs_7395.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_7392 = Frame::module(frame.globals.clone()); let mut __function_7394 = NativeFunction::qualified_with_origin("_trouble".into(), "_trouble".into(), "bot.compose.fallback".into(), __attrs_7395, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/compose/fallback.py", first: 12961, last: 12981, qualname: "_trouble" }, closure: __closure_7392.clone(), freevars: vec![] }, move |rt, args| __py_320::_trouble(rt, __closure_7392.clone(), &__signature_7393, args)); __function_7394 })?;
