frame.store("_a_refusal_to_answer", { let __default_8553 = Value::None; let __signature_8551 = Signature { name: "_a_refusal_to_answer".into(), positional: vec!["clean".into(),"memory".into(),"words".into()], positional_only: 0, defaults: vec![__default_8553], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_8554 = Value::dict(); __attrs_8554.dict_set(Value::from("__doc__"), Value::from("The pool for a line that reports somebody else's no, or None.\n\n    The person did what the answer said and it was turned down - by a boss, a landlord, a bank, a\n    council, or the person they live with. The composer has the answer to that and the ack does\n    not: said back it is \"Got it - your boss said no\", which is the person's own line with nothing\n    added. Read in one place so the reply and the claim cannot drift apart (`reads_as_a_refusal`\n    asks the same question for the arbiter).\n\n    Narrow on purpose: no question mark, fifteen words at most, a party who can be asked again or\n    an answer above for the no to be about, no no from somebody treating them, and nothing that\n    reads as a fault to repair. A thread with a death or a live safety answer keeps its own line.\n    "))?; __attrs_8554.dict_set(Value::from("__defaults__"), Value::tuple(__signature_8551.defaults.clone()))?; let __kwdefaults_8555 = Value::dict(); __attrs_8554.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_8550 = Frame::module(frame.globals.clone()); let mut __function_8552 = NativeFunction::qualified_with_origin("_a_refusal_to_answer".into(), "_a_refusal_to_answer".into(), "bot.compose.fallback".into(), __attrs_8554, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/compose/fallback.py", first: 16201, last: 16261, qualname: "_a_refusal_to_answer" }, closure: __closure_8550.clone(), freevars: vec![] }, move |rt, args| __py_420::_a_refusal_to_answer(rt, __closure_8550.clone(), &__signature_8551, args)); __function_8552 })?;
